chapter.para:

     Variable राम्ररी जाँच नगर्दा निम्तिने नतिजा....


<?php

// Remove a file from the user's home directory
$username = $_POST['user_submitted_name'];
$userfile = $_POST['user_submitted_filename'];
$homedir  = "/home/$username";

unlink("$homedir/$userfile");

echo "The file has been deleted!";

?>



   Username र filename दुवै user form बाट पठाउन मिल्ने भएकाले, कसैले अरू कसैको username र filename पठाउन सक्छ र अनुमति नभएको अवस्थामा पनि अरूको file मेटाउन सक्छ। यस्तो अवस्थामा, तपाईंले अर्कै किसिमको authentication तरिका अपनाउनुपर्छ। यदि पठाइएका variables मा
   "../etc/" र "passwd" राखियो भने के हुन सक्छ विचार गर्नुहोस्। तब त्यो code व्यवहारिक रूपमा यस्तो देखिनेछ:

     ... एक filesystem आक्रमण


<?php

// Removes a file from anywhere on the hard drive that
// the PHP user has access to. If PHP has root access:
$username = $_POST['user_submitted_name']; // "../etc"
$userfile = $_POST['user_submitted_filename']; // "passwd"
$homedir  = "/home/$username"; // "/home/../etc"

unlink("$homedir/$userfile"); // "/home/../etc/passwd"

echo "The file has been deleted!";

?>



    यस्ता समस्याहरू रोक्नका लागि तपाईंले दुईवटा महत्वपूर्ण उपायहरू अपनाउनुपर्छ।



       PHP web user binary लाई सीमित permissions मात्र दिनुहोस्।




       पठाइएका (submitted) सबै variables को जाँच गर्नुहोस्।



    यहाँ सुधारिएको script दिइएको छ:

     अझ सुरक्षित file name जाँच


<?php

// Removes a file from the hard drive that
// the PHP user has access to.
$username = $_SERVER['REMOTE_USER']; // using an authentication mechanism
$userfile = basename($_POST['user_submitted_filename']);
$homedir  = "/home/$username";

$filepath = "$homedir/$userfile";

if (file_exists($filepath) && unlink($filepath)) {
    $logstring = "Deleted $filepath\n";
} else {
    $logstring = "Failed to delete $filepath\n";
}

$fp = fopen("/home/logging/filedelete.log", "a");
fwrite($fp, $logstring);
fclose($fp);

echo htmlentities($logstring, ENT_QUOTES);

?>



    तर, यो पनि पूर्ण रूपमा कमजोरीरहित छैन। यदि तपाईंको authentication system ले users लाई आफ्नै user login बनाउन दिन्छ, र कुनै user ले "../etc/" लाई login नामका रूपमा चुन्यो भने, system फेरि जोखिममा पर्छ। यही कारणले गर्दा, तपाईंले अझ विशिष्ट (customized) जाँच लेख्न रुचाउन सक्नुहुन्छ:

     अझ सुरक्षित file name जाँच


<?php

$username     = $_SERVER['REMOTE_USER']; // using an authentication mechanism
$userfile     = $_POST['user_submitted_filename'];
$homedir      = "/home/$username";

$filepath     = "$homedir/$userfile";

if (!ctype_alnum($username) || !preg_match('/^(?:[a-z0-9_-]|\.(?!\.))+$/iD', $userfile)) {
    die("Bad username/filename");
}

// etc.

?>
